/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::CHUNK_OUT_OF_RANGE,
    error_codes::TERMINAL_STATE,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `backup/get-chunk:notFound`
    ///
    /// The recipient holds no live chunked export bundle under this identifier that this producer may act on. Deliberately conflates "no such bundle", "an import bundle", "a stream bundle", and "not yours" — see Correlation.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "backup/get-chunk:notFound",
        retryable: false,
    };
    /// `backup/get-chunk:chunkOutOfRange`
    ///
    /// `index` is not below the bundle's `chunkCount`. Returned only to the bundle's creator, who already holds the manifest, so it discloses nothing.
    ///
    /// Declared `retryable: false`.
    pub const CHUNK_OUT_OF_RANGE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "backup/get-chunk:chunkOutOfRange",
        retryable: false,
    };
    /// `backup/get-chunk:terminalState`
    ///
    /// The bundle was acknowledged with complete-export, aborted, or has expired. Nothing more will be served under this identifier; a new export is needed.
    ///
    /// Declared `retryable: false`.
    pub const TERMINAL_STATE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "backup/get-chunk:terminalState",
        retryable: false,
    };
}
#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000013\",\n  \"type\": \"https://trusttasks.org/spec/backup/get-chunk/0.1#request\",\n  \"issuer\": \"did:example:operator\",\n  \"recipient\": \"did:example:node\",\n  \"issuedAt\": \"2026-01-01T02:01:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000fb\",\n  \"payload\": {\n    \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\",\n    \"index\": 2\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000014\",\n  \"type\": \"https://trusttasks.org/spec/backup/get-chunk/0.1#response\",\n  \"issuer\": \"did:example:node\",\n  \"recipient\": \"did:example:operator\",\n  \"issuedAt\": \"2026-01-01T02:01:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000fb\",\n  \"payload\": {\n    \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\",\n    \"index\": 2,\n    \"digestMultibase\": \"zQmTcWLvAPe4Txz32vVqZe5jgX4nBPiaBsTTCp4bLXDMzTT\",\n    \"data\": \"YmFja3VwLXRhaWwh\",\n    \"expiresAt\": \"2026-01-01T02:11:01Z\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing `index`. There is no 'next chunk' — the producer names what it wants, which is what makes a retry or a resume a plain repeat rather than a cursor the recipient must track.",
                "{\n  \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\"\n}",
            ),
            (
                "Negative `index`. Caught by the schema rather than left to be read as 'from the end' by a lenient consumer.",
                "{\n  \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\",\n  \"index\": -1\n}",
            ),
            (
                "`index` beyond the 4096-chunk bound. No manifest can describe it, so it never reaches a lookup.",
                "{\n  \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\",\n  \"index\": 4096\n}",
            ),
            (
                "`bundleId` that is not a UUID. The pattern keeps a crafted handle from reaching the recipient's store as a lookup key.",
                "{\n  \"bundleId\": \"latest\",\n  \"index\": 0\n}",
            ),
            (
                "Unknown top-level member — additionalProperties: false catches `transportToken`. A chunked retrieval is authorized by the authenticated sender, never by a bearer token; accepting one here would invite implementations to treat it as sufficient.",
                "{\n  \"bundleId\": \"5b1f4a2e-7c3d-4e8f-9a6b-2d0c1e3f4a5b\",\n  \"index\": 0,\n  \"transportToken\": \"dGhpcy1pcy1hLW9uZS1zaG90LWJlYXJlci10b2tlbg\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
